import{_ as a,o as t,c as l,a8 as i}from"./chunks/framework.CiGKN4gy.js";const u=JSON.parse('{"title":"常见问题与解答","description":"","frontmatter":{"title":"常见问题与解答","lang":"zh-CN"},"headers":[],"relativePath":"zh-cn/guide/faq.md","filePath":"zh-cn/guide/faq.md","lastUpdated":1790353258000}'),o={name:"zh-cn/guide/faq.md"};function n(s,e,r,d,c,p){return t(),l("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjIlRTUlQjglQjglRTglQTclODElRTklOTclQUUlRTklQTIlOTglRTQlQjglOEUlRTglQTclQTMlRTclQUQlOTQlMjIlMkMlMjJsYW5nJTIyJTNBJTIyemgtQ04lMjIlMkMlMjJkYXRlJTIyJTNBMTc5MDM1MzI1ODAwMCU3RA=="},[...e[0]||(e[0]=[i(`<h1 id="常见问题与解答" tabindex="-1">常见问题与解答 <a class="header-anchor" href="#常见问题与解答" aria-label="Permalink to &quot;常见问题与解答&quot;">​</a></h1><h2 id="本模块的性能如何" tabindex="-1">本模块的性能如何？ <a class="header-anchor" href="#本模块的性能如何" aria-label="Permalink to &quot;本模块的性能如何？&quot;">​</a></h2><p>IP 检查和 CC 防御花费常数时间，其它的检查花费 <code>O(nm)</code> 的时间，其中 <code>n</code> 是相关规则的条数，<code>m</code> 为执行正则匹配的时间复杂度，但是每次检查过后会自动缓存本次检查的结果，下次检查相同的目标时就可以使用缓存而不是检查全部的规则。不会缓存 POST 请求体的检查结果。</p><h2 id="缓存策略" tabindex="-1">缓存策略 <a class="header-anchor" href="#缓存策略" aria-label="Permalink to &quot;缓存策略&quot;">​</a></h2><p>LRU</p><h2 id="模块的内置变量与指令-if" tabindex="-1">模块的内置变量与指令 <code>if</code> <a class="header-anchor" href="#模块的内置变量与指令-if" aria-label="Permalink to &quot;模块的内置变量与指令 \`if\`&quot;">​</a></h2><p>简而言之，由于 NGINX 的状态机模型，你无法将本模块的任何内置变量（如 <code>$waf_rule_type</code>）用于指令 <code>if</code>，但是指令 <code>access_log</code> 的参数 <code>if</code> 除外。</p><h2 id="ngx-http-access-module" tabindex="-1"><code>ngx_http_access_module</code> <a class="header-anchor" href="#ngx-http-access-module" aria-label="Permalink to &quot;\`ngx_http_access_module\`&quot;">​</a></h2><p>当本模块与 <code>ngx_http_access_module</code> 一起使用时，<code>ngx_http_access_module</code> 会先于本模块运行。</p><h1 id="post检测失效" tabindex="-1">post检测失效 <a class="header-anchor" href="#post检测失效" aria-label="Permalink to &quot;post检测失效&quot;">​</a></h1><p>本模块出于性能考虑只会在 Post 请求体在内存中时检查，若不在内存中则跳过检查。 您可以通过修改配置文件来解决这个问题。</p><div class="language-nginx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">nginx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">http</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    client_body_buffer_size </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10M</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    client_body_in_file_only </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><a href="https://nginx.org/en/docs/http/ngx_http_core_module.html#client_body_buffer_size" target="_blank" rel="noreferrer">client_body_buffer_size 的说明</a> 和 <a href="https://nginx.org/en/docs/http/ngx_http_core_module.html#client_body_in_file_only" target="_blank" rel="noreferrer">client_body_in_file_only 的说明</a>。</p><h2 id="可以在运行时修改规则么" tabindex="-1">可以在运行时修改规则么？ <a class="header-anchor" href="#可以在运行时修改规则么" aria-label="Permalink to &quot;可以在运行时修改规则么？&quot;">​</a></h2><p>不可以，本模块只会在 nginx 读取配置时读取规则。nginx 会在启动和 reload 时读取配置。</p><h2 id="cdn-对-ip-检查的影响" tabindex="-1">CDN 对 IP 检查的影响 <a class="header-anchor" href="#cdn-对-ip-检查的影响" aria-label="Permalink to &quot;CDN 对 IP 检查的影响&quot;">​</a></h2><p>如果你使用 <a href="https://nginx.org/en/docs/http/ngx_http_realip_module.html" target="_blank" rel="noreferrer">ngx_http_realip_module</a> 获取真实 IP 的话，则本模块在检查 IP 时就会使用真实的 IP。</p><h2 id="正则表达式拒绝服务攻击-redos" tabindex="-1">正则表达式拒绝服务攻击（ReDoS） <a class="header-anchor" href="#正则表达式拒绝服务攻击-redos" aria-label="Permalink to &quot;正则表达式拒绝服务攻击（ReDoS）&quot;">​</a></h2><p>ReDoS 是指使用的正则表达式存在缺陷时，攻击者可以使用一个精心构造的字符串来大量地消耗服务器的资源，比如导致正则引擎的灾难性的回溯。</p><p>本模块有两种措施可以用来缓解此类攻击。</p><ul><li><p>本模块使用的 PCRE 库执行正则表达式，PCRE 在编译时即可指定主循环的计数器上限，超出上限自动停止。默认上限为 500000。你也可以在编译时手动调整，详见 <a href="https://www.pcre.org/current/doc/html/pcre2build.html#SEC11" target="_blank" rel="noreferrer">pcre2 build man page</a>。</p></li><li><p>本模块会缓存所有正则的检查结果（POST 检查除外），这样在不触发缓存淘汰流程的情况下，下次遇到用于攻击的字符串也无需再次执行正则表达式。</p></li></ul><h2 id="fork-failed-while-spawning-worker-process-12-cannot-allocate-memory" tabindex="-1">fork() failed while spawning &quot;worker process&quot; (12: Cannot allocate memory) <a class="header-anchor" href="#fork-failed-while-spawning-worker-process-12-cannot-allocate-memory" aria-label="Permalink to &quot;fork() failed while spawning &quot;worker process&quot; (12: Cannot allocate memory)&quot;">​</a></h2><p>可能是过多地使用 <code>nginx -s reload</code> 导致的，本模块会在读取配置的时候申请一些内存，但是不知为何 <code>nginx -s reload</code> 之后这些内存不会立即释放，所以短时间内频繁 <code>nginx -s reload</code> 就极可能导致这个错误。</p><h2 id="panic-unprotected-error-in-call-to-lua-api-attempt-to-index-a-nil-value" tabindex="-1">PANIC: unprotected error in call to Lua API (attempt to index a nil value) <a class="header-anchor" href="#panic-unprotected-error-in-call-to-lua-api-attempt-to-index-a-nil-value" aria-label="Permalink to &quot;PANIC: unprotected error in call to Lua API (attempt to index a nil value)&quot;">​</a></h2><p>请检查你的 <code>libmodsecurity</code> 的版本，在测试中 <code>libmodsecurity v3.0.3</code> 存在这个 Bug，请升级到 <code>libmodsecurity v3.0.5</code>。</p>`,25)])])}const _=a(o,[["render",n]]);export{u as __pageData,_ as default};
